150	/**
151	 * The statements taken for people on a sheet. Taking one records the person's due-total at that
152	 * moment and binds each of their claims that counts to the figure it has then; their other claims
153	 * are left unbound, their due live again. A claim's due fixed when settled stays as it is.
154	 */
155	@Service
156	public class StatementService {
157	
158	    /** A person's statements: how many, and the last one's due-total (null when n/a) and date. */
159	    public record Summary(Long personId, int count, BigDecimal lastDueTotal, LocalDate lastDate) {}
160	
161	    /** A statement just taken, with the person's claims as they now stand. */
162	    public record Taken(Summary summary, List<Claim> claims) {}
163	
164	    private final StatementRepository statements;
165	    private final PersonRepository people;
166	    private final ClaimRepository claims;
167	    private final ClaimService claimService;
168	    private final RateService rates;
169	    private final SheetRepository sheets;
170	    private final Audit audit;
171	
172	    public StatementService(StatementRepository statements, PersonRepository people, ClaimRepository claims,
173	            ClaimService claimService, RateService rates, SheetRepository sheets, Audit audit) {
174	        this.statements = statements;
175	        this.people = people;
176	        this.claims = claims;
177	        this.claimService = claimService;
178	        this.rates = rates;
179	        this.sheets = sheets;
180	        this.audit = audit;
181	    }
182	
183	    /** Each person's statements on the sheet, for those with any. */
184	    @Transactional(readOnly = true)
185	    public List<Summary> summaries(String sheetId) {
186	        Map<Long, List<Statement>> byPerson = new LinkedHashMap<>();
187	        for (Statement s : statements.findBySheetIdOrderByIdAsc(sheetId)) {
188	            byPerson.computeIfAbsent(s.getPersonId(), id -> new ArrayList<>()).add(s);
189	        }
190	        return byPerson.entrySet().stream().map(e -> summaryOf(e.getKey(), e.getValue())).toList();
191	    }
192	
193	    @Transactional
194	    public Taken take(String sheetId, String user, Long personId) {
195	        // Lock the sheet so the claims and rates read are not changed while the statement is taken.
196	        LocalDate today = sheets.findForUpdate(sheetId).orElseThrow(SheetNotFoundException::new).getToday();
197	        Person person = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
198	        List<Claim> theirs = claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId);
199	        boolean fixed = false;
200	        BigDecimal total = BigDecimal.ZERO.setScale(2);
201	        int counted = 0;
202	        for (Claim claim : theirs) {
203	            if (!claim.getStatus().counts()) {
204	                claim.unstate();
205	                continue;
206	            }
207	            BigDecimal figure = claimService.figureOf(sheetId, person, claim);
208	            if (claim.getSettledDue() != null || (claim.isStated() && claim.getStatedDue() != null)) fixed = true;
209	            claim.state(figure);
210	            if (figure != null) total = total.add(figure);
211	            counted++;
212	        }
213	        // As on screen: n/a when their grade has no rate today and none of the counted claims has a fixed due.
214	        BigDecimal dueTotal = fixed || rates.on(sheetId, person.getGrade(), today).isPresent() ? total : null;
215	        claims.saveAllAndFlush(theirs);
216	        statements.saveAndFlush(new Statement(sheetId, personId, dueTotal, today, user.strip()));
217	        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user.strip() + " name=" + person.getName()
218	                + " due-total=" + (dueTotal == null ? "n/a" : dueTotal.toPlainString()) + " claims=" + counted);
219	        return new Taken(summaryOf(personId, statements.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, personId)),
220	                theirs);
221	    }
222	
223	    private static Summary summaryOf(Long personId, List<Statement> list) {
224	        Statement last = list.get(list.size() - 1);
225	        return new Summary(personId, list.size(), last.getDueTotal(), last.getDate());
226	    }
227	}
