402	package net.officefloor.hq.app.claim;
403	
404	import java.math.BigDecimal;
405	import java.math.RoundingMode;
406	import java.time.LocalDate;
407	import java.util.List;
408	import net.officefloor.hq.app.Audit;
409	import net.officefloor.hq.app.person.Person;
410	import net.officefloor.hq.app.person.PersonNotFoundException;
411	import net.officefloor.hq.app.person.PersonRepository;
412	import net.officefloor.hq.app.rate.Rate;
413	import net.officefloor.hq.app.rate.RateService;
414	import net.officefloor.hq.app.sheet.SheetService;
415	import org.springframework.stereotype.Service;
416	import org.springframework.transaction.annotation.Transactional;
417	
418	/**
419	 * The claims on a sheet: listed newest first, added to a person and edited one at a time. A claim
420	 * given no date takes the sheet's today. A claim is added as DRAFT and moves through its statuses
421	 * as {@link ClaimStatus} allows; a change it does not allow is refused. Opening a claim gives it
422	 * the sheet's next number; voiding it clears the number, which is never given again. Settling it
423	 * fixes its due at its person's grade rate of the moment on the claim's date; with no such rate it
424	 * stays live. The user who opened a claim cannot settle it.
425	 */
426	@Service
427	public class ClaimService {
428	
429	    private final ClaimRepository claims;
430	    private final PersonRepository people;
431	    private final RateService rates;
432	    private final SheetService sheets;
433	    private final Audit audit;
434	
435	    public ClaimService(ClaimRepository claims, PersonRepository people, RateService rates, SheetService sheets,
436	            Audit audit) {
437	        this.claims = claims;
438	        this.people = people;
439	        this.rates = rates;
440	        this.sheets = sheets;
441	        this.audit = audit;
442	    }
443	
444	    @Transactional(readOnly = true)
445	    public List<Claim> list(String sheetId) {
446	        return claims.findBySheetIdOrderByIdDesc(sheetId);
447	    }
448	
449	    @Transactional
450	    public Claim add(String sheetId, String user, Long personId, BigDecimal amount, LocalDate date, String note) {
451	        Person person = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
452	        Claim claim = claims.saveAndFlush(new Claim(sheetId, personId, amount, dateOrToday(sheetId, date), note));
453	        record("CLAIM_ADDED", sheetId, user, person, claim);
454	        return claim;
455	    }
456	
457	    @Transactional
458	    public Claim edit(String sheetId, String user, Long id, BigDecimal amount, LocalDate date, String note) {
459	        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
460	        claim.setAmount(amount);
461	        claim.setDate(dateOrToday(sheetId, date));
462	        claim.setNote(note);
463	        Claim saved = claims.saveAndFlush(claim);
464	        Person person = people.findByIdAndSheetId(saved.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
465	        record("CLAIM_EDITED", sheetId, user, person, saved);
466	        return saved;
467	    }
468	
469	    @Transactional
470	    public Claim changeStatus(String sheetId, String user, Long id, ClaimStatus next) {
471	        // Opening takes the sheet's next number, locking the sheet first so the claim is read only
472	        // once no other open on the sheet is under way; a refusal rolls the number back.
473	        Long opened = next == ClaimStatus.OPEN ? sheets.nextClaimNumber(sheetId) : null;
474	        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
475	        if (!claim.getStatus().canBecome(next)) {
476	            throw new ClaimStatusRefusedException();
477	        }
478	        if (next == ClaimStatus.SETTLED && user.strip().equals(claim.getOpenedBy())) {
479	            throw new ClaimSettledByOpenerException();
480	        }
481	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
482	        Long number = claim.getNumber();
483	        switch (next) {
484	            case OPEN -> {
485	                number = opened;
486	                claim.setNumber(number);
487	                claim.setOpenedBy(user.strip());
488	            }
489	            case SETTLED -> claim.setSettledDue(dueOf(sheetId, person, claim));
490	            case VOID -> claim.setNumber(null);
491	            default -> {}
492	        }
493	        claim.setStatus(next);
494	        Claim saved = claims.saveAndFlush(claim);
495	        String event = switch (next) {
496	            case OPEN -> "CLAIM_OPENED";
497	            case SETTLED -> "CLAIM_SETTLED";
498	            case VOID -> "CLAIM_VOIDED";
499	            case DRAFT -> throw new IllegalStateException();
500	        };
501	        String due = next == ClaimStatus.SETTLED
502	                ? " due=" + (saved.getSettledDue() == null ? "n/a" : saved.getSettledDue().setScale(2).toPlainString())
503	                : "";
504	        record(event, sheetId, user, person, saved, number, due);
505	        return saved;
506	    }
507	
508	    /**
509	     * A claim's figure now: the due fixed when it was settled, else the due bound by its person's
510	     * last statement, else its live due; null when it has none.
511	     */
512	    public BigDecimal figureOf(String sheetId, Person person, Claim claim) {
513	        if (claim.getSettledDue() != null) return claim.getSettledDue();
514	        if (claim.isStated()) return claim.getStatedDue();
515	        return dueOf(sheetId, person, claim);
516	    }
517	
518	    /** A claim's amount times its person's grade rate on its date, rounded half to even to cents; null with no rate. */
519	    private BigDecimal dueOf(String sheetId, Person person, Claim claim) {
520	        return rates.on(sheetId, person.getGrade(), claim.getDate())
521	                .map(Rate::getPct)
522	                .map(pct -> claim.getAmount().multiply(pct).movePointLeft(2).setScale(2, RoundingMode.HALF_EVEN))
523	                .orElse(null);
524	    }
525	
526	    private void record(String event, String sheetId, String user, Person person, Claim claim) {
527	        record(event, sheetId, user, person, claim, claim.getNumber(), "");
528	    }
529	
530	    /** A claim's audit line; one about a claim with a number has it, then any extra fields. */
531	    private void record(String event, String sheetId, String user, Person person, Claim claim, Long number,
532	            String extra) {
533	        audit.recordOnCommit(event + " sheet=" + sheetId + " by=" + user.strip() + " person=" + person.getName()
534	                + " amount=" + claim.getAmount().setScale(2).toPlainString() + " date=" + claim.getDate()
535	                + (number != null ? " number=" + number : "") + extra);
536	    }
537	
538	    private LocalDate dateOrToday(String sheetId, LocalDate date) {
539	        return date != null ? date : sheets.today(sheetId);
540	    }
