933	
934	/**
935	 * The people on a sheet: listed in the order they were added, added and edited one at a time. A
936	 * name already used by another person on the sheet (ignoring case and surrounding spaces) is
937	 * refused, and so is an edit made from a version of the person someone else has saved since.
938	 */
939	@Service
940	public class PersonService {
941	
942	    private final PersonRepository people;
943	    private final SheetRepository sheets;
944	    private final Audit audit;
945	
946	    public PersonService(PersonRepository people, SheetRepository sheets, Audit audit) {
947	        this.people = people;
948	        this.sheets = sheets;
949	        this.audit = audit;
950	    }
951	
952	    @Transactional(readOnly = true)
953	    public List<Person> list(String sheetId) {
954	        return people.findBySheetIdOrderByIdAsc(sheetId);
955	    }
956	
957	    @Transactional
958	    public Person add(String sheetId, String user, String name, String grade) {
959	        if (!sheets.existsById(sheetId)) throw new SheetNotFoundException();
960	        requireUnused(sheetId, name, null);
961	        Person person = saveUnique(new Person(sheetId, name, grade));
962	        record("PERSON_ADDED", sheetId, user, person);
963	        return person;
964	    }
965	
966	    @Transactional
967	    public Person edit(String sheetId, String user, Long id, long version, String name, String grade) {
968	        Person person = people.findByIdAndSheetId(id, sheetId).orElseThrow(PersonNotFoundException::new);
969	        if (person.getVersion() != version) throw new PersonVersionConflictException();
970	        requireUnused(sheetId, name, id);
971	        person.setName(name);
972	        person.setGrade(grade);
973	        Person saved = saveUnique(person);
974	        record("PERSON_EDITED", sheetId, user, saved);
975	        return saved;
976	    }
977	
978	    private void record(String event, String sheetId, String user, Person person) {
979	        audit.recordOnCommit(event + " sheet=" + sheetId + " by=" + user.strip()
980	                + " name=" + person.getName() + " grade=" + person.getGrade());
981	    }
982	
983	    private void requireUnused(String sheetId, String name, Long self) {
984	        people.findBySheetIdAndNameKey(sheetId, Person.keyOf(name))
985	                .filter(other -> !other.getId().equals(self))
986	                .ifPresent(other -> { throw new DuplicatePersonNameException(); });
987	    }
988	
989	    /** Writes the person now, so a name taken meanwhile by another user is refused by the store. */
990	    private Person saveUnique(Person person) {
991	        try {
992	            return people.saveAndFlush(person);
993	        } catch (DataIntegrityViolationException e) {
994	            throw new DuplicatePersonNameException();
995	        } catch (ObjectOptimisticLockingFailureException e) {
996	            throw new PersonVersionConflictException();
997	        }
