1126	    /** The grade's rate on the date: the one with the latest from-date on or before it, if any. */
1127	    @Transactional(readOnly = true)
1128	    public Optional<Rate> on(String sheetId, String grade, LocalDate date) {
1129	        return rates.findBySheetIdAndGrade(sheetId, grade).stream()
1130	                .filter(rate -> rate.appliesOn(date))
1131	                .max(Comparator.comparing(Rate::getFromDate, Comparator.nullsFirst(Comparator.naturalOrder())));
1132	    }
