1138	        Optional<Rate> existing = from == null
1139	                ? rates.findBySheetIdAndGradeAndFromDateIsNull(sheetId, grade)
1140	                : rates.findBySheetIdAndGradeAndFromDate(sheetId, grade, from);
1141	        Rate rate = existing.orElseGet(() -> new Rate(sheetId, grade, from, pct));
1142	        rate.setPct(pct);
