1144	        audit.recordOnCommit("RATE_SET sheet=" + sheetId + " by=" + user.strip()
1145	                + " grade=" + saved.getGrade() + " rate=" + saved.getPct().setScale(2).toPlainString()
1146	                + (saved.getFromDate() != null ? " from=" + saved.getFromDate() : ""));
1147	        return saved;
